     "title": "비 오는 밤의 코드",
     "summary": "서울에서 펜과 수채로 하루를 그리는 조아름의 평범한 하루. 저녁에 아버지의 연구실(소울 아이즈 랩스)에 도시락을 들고 들렀다가, 천둥 치는 밤 모니터에 쏟아지는 알 수 없는 코드와 오류가 풀리는 순간을 함께 본다. 번개 빛에 비친 유리창에 잠깐 어린양의 실루엣이 스치고, 아름은 그것을 스케치북에 그려 둔다.",
