     "label": "1화",
     "title": "초원의 별",
     "summary": "가족이 몽골 단기선교를 떠난다. 아름은 'Pureday' 라이브 방송을, 하임은 아버지 회사의 베타 글래스(하이퍼 글래스 v04)와 드론을 연동한다. 테를지 외곽의 밤, 은하수 아래 소리 없는 마른번개가 치자 하임의 글래스에만 코드가 쏟아지고 초원 위로 금빛 경계선이 겹친다. 빛의 중심에서 어린양 타미가 나타나 남매를 기암괴석 지대로 이끌고, 검독수리 아퀼라가 내려앉고, 앵무새 페이가 \"퓨어랜드의 보호막이 깨졌어요\"라고 통역한다. 끝에 하임이 글래스를 아름에게 씌워 주고, 아름도 하늘을 가르는 금빛 성벽의 금 간 자국을 본다.",
     "scenes": 70,
