     "label": "9화",
     "title": "용장",
     "summary": "8화의 새벽, 서울 미대 옥상. 아퀼라가 날개를 펴자 허공에 **빛의 틈**이 열리고, 남매는 퓨어랜드 **서쪽 국경 마을 레체아**로 간다(박사는 소울 아이즈 랩스에서 글래스 데이터로 지켜본다). 은바와 다시 만나 \"이번엔 내가 먼저 뛸게\" 약속을 지키려는 하임. 단 지파의 후손 **아라이 민족**이 사는 마을은 용보다 먼저 **서로**와 싸우고 있다 — 대장장이 패와 방앗간 패가 \"누가 성문을 열어 뒀나\"로 맞서고, 모든 사람의 그림자 끝에서 가시덤불이 자란다. 종이 울리고 **분쟁의 용장**이 내려앉는다 — **머리가 셋**인 잿빛 용 **아포피스**, 등에 검은 가시덤불 등뼈. 세 머리가 대장장이 패·방앗간 패·'이방인' 남매에게 따로 속삭이고, 숨결이 사람들 사이에 가시 울타리를 세운다. 하임은 혼자 앞서 뛰었다가 꼬리에 맞아 쓰러진다. 그때 두 어른의 연장 사이에 낀 작은 여자아이를 보고, 실기실에서 두 사람 사이로 걸어 들어가던 누나를 떠올린다. 하임은 용이 아니라 **광장 한가운데**로 걸어가, 목봉을 가로로 들어 망치와 갈퀴를 막는다. \"지금 싸울 상대는 서로가 아니에요.\" 두 패가 함께 성문을 닫는 순간 하임의 발에 **평안의 복음의 신**이 맺히고, 장갑과 장비가 세 번째 단계로 강화된다(**사슬 장갑 + 목봉에 빛의 창날 → 창**). 가시 울타리가 무너지고, 하나 된 마을 앞에서 용장의 세 머리는 서로 엉킨다. 아름의 화살, 하늘군과 아퀼라, 은바와 하임의 창 — 용장은 쓰러지지 않고 북서쪽 구름으로 달아난다. 끝: 마을 예배당 — 아라이 사람들의 기도 \"여호와여, 나는 주의 구원을 기다리나이다\"(창 49:18), 낡은 벽화 — **옛 뱀이 큰 용이 되었고, 그 아래 다섯 용장**(계 12:9). 사제는 아라이가 '길의 뱀'(창 49:17)이라 불리고 열두 지파 이름에서도 빠진(계 7장) 단 지파의 후손이라 말하고, 하임은 황금 성의 **열두 개의 빈 방패**를 떠올린다(12화 복선). 나흘 뒤 서울, 졸업 전시 첫날. 텅 빈 입구를 보는 서진의 발끝 그림자에서 **잿빛 불씨**가 피어오른다(10화 예고 — 낙심의 용장).",
     "scenes": 70,
