     "num": 11,
     "label": "11화",
     "title": "연구실 습격",
     "summary": "10화 끝의 같은 밤. 소울 아이즈 랩스의 모니터가 전부 잿빛 잡음으로 일그러지고, 추락한 드론이 창에 금을 낸다. 보통 눈에는 돌풍이지만 글래스 시점에는 **비룡대**가 벽을 연기처럼 뚫고 들어와 서버 랙에 매달려 잡음 안개를 뿜는다. 비룡은 야근하던 연구원 **하나**의 귓가에 \"다 지워, 이건 버그야\"라고 속삭이고, 하나는 비상 스위치에 손을 올린다. 박사가 막는다 — \"그건 스물여덟 해야.\" 같은 시각 황금 성: 비룡대가 **기록관의 탑**을 덮쳐 두루마리의 그림을 잿빛으로 지운다. 하임·은바·견습 창병이 막아서지만, 하임의 글래스에 서울 연구실의 아버지가 겹쳐 보인다. 기록관: \"거울이다. 저들이 노리는 건 네 아버지가 스물여덟 해 동안 적어 온 것.\" 7화의 견습 창병이 \"이번엔 제가 할아버지 곁에 있을게요\"라며 탑을 맡고, 아퀼라가 연 빛의 틈으로 하임이 서울로 돌아간다. 서버실: 비룡이 박사에게 \"네가 본 건 번개의 버그였어, 스물여덟 해를 헛살았다\"고 속삭이고, 박사는 무릎이 꺾여 노트를 떨어뜨린다. 하나가 차단기 레버로 걸어가고 도윤도 속삭임에 주저앉는다. 그 순간 빛의 틈에서 하임이 내린다. 창으로 쳐내도 비룡은 벽을 뚫고 끝없이 들어오고, \"넌 늘 늦어, 아버지도 못 지켜\"라는 속삭임에 흔들린다. 하임은 바닥의 노트를 집어 아버지 손에 쥐여 준다 — \"아빠가 본 거, 진짜야. 내가 봤어. 아빠 혼자 본 게 아니야.\" 아버지 앞에 서서 왼팔을 들자 **믿음의 방패**(히브리서 11:1)가 **카이트 실드**로 맺히고 사슬 장갑이 **강철 건틀릿**이 된다 — 하임 4단계. 비룡은 방패에 닿는 대로 연기로 흩어지고, 거울 원리로 황금 성 큰 홀의 열두 방패 중 하나가 금빛으로 타오른다(남매 몫 두 개에 더해 하나 더). 연구실이 돌아오고 박사는 우는 하나에게 1998년의 스케치를 보여 준다 — \"속삭임은 누구에게나 와. 중요한 건 누가 옆에 있느냐지.\" 새벽, 아름이 달려오고 박사는 선반의 **하이퍼 글래스 시제품 열두 개**를 가리킨다 — \"열두 명을 찾아야 한다. 저들보다 먼저.\" 끝: 옥상 난간에 **흰 머리의 큰 독수리**(12화 루아 예고)가 발목에 작은 두루마리를 매단 채 앉아 있다.",
     "scenes": 70,
