     "num": 13,
     "label": "13화",
     "title": "구원의 투구",
     "summary": "12화 라이브 다음 날 아침. 아름의 휴대폰이 터진다 — 하트 사이에 작은 **왕관** 아이콘과 \"세 번째 금빛 창문은 너야, 퓨어데이가 첫째야\" 같은 속삭임. 하임의 글래스엔 금빛 선이 여러 방향으로. 연구실 선반의 글래스 셋이 저마다 다른 색으로 빛나고, 박사는 아름에게 **푸른 점 글래스**를 건넨다 — 아름이 처음으로 글래스를 쓴다. 지도의 황금 성 위에 왕관 그림자 — \"교만이다. 가장 조용히 오는 용장.\" 황금 성: **교만의 용장 라합**(상아빛 금빛 용, 상아 뿔 왕관, 공작 깃 같은 금빛 가시, 금빛 먼지 숨)이 성문 앞에서 \"열두 자리 중 첫째는 누구지?\" 금빛 먼지가 닿은 기사들 머리 위에 **환상의 왕관**이 맺혀 서로 지휘권을 다툰다(견습 창병은 케틀 투구를 꾹 눌러 써서 왕관이 안 맺힘). 남매가 성벽에 오르고 먼지가 둘을 갈라놓는다 — 아름에게 \"네가 첫째, 동생은 네 그림자\", 하임에게 \"진짜 방패는 너\". 둘 다 왕관을 쓴 채 처음으로 서로에게 차가운 말을 한다. 은바가 아름의 왕관에 으르렁거리고 견습 창병이 소매를 잡는다. 라합이 성문을 밀고 큰 홀로 — 바닥의 돌 뚜껑을 긁으며 \"열두 자리는 전부 내 것\". 남매가 따로 뛰어들고, 라합의 꼬리가 기둥을 치자 들보가 하임 쪽으로 — **아름이 활을 버리고 하임을 밀어내고 깔린다**(\"네가 먼저 가. 넌 나보다 먼저 보는 애니까\") → 아름의 왕관이 깨진다. 라합의 숨이 쏟아지자 **하임이 방패를 버리고 아름 위에 엎드려 덮는다**(\"누나 없이 보는 건 의미 없어\") → 하임의 왕관도 깨진다. 두 글래스가 동시에 빛나 **투구의 눈가리개**가 되고 투구가 맺힌다(살전 5:8) — 판금 건틀릿, 하임의 창 → **미늘창**, 아름의 장궁 → **금빛 상감**. 5단계. 하임이 들보를 들고 아름이 빠져나와 \"같이.\" 빛의 화살과 미늘창이 라합의 왕관 뿔 하나를 꺾고 라합은 \"둘이면서 하나라니, 기억해 두마\"라며 퇴각. 기사들의 왕관이 사라지고, 연구실 지도의 글래스 신호 두 개가 투구 모양으로 바뀐다 — \"글래스는 원래 그걸 위해 있었어.\" 끝: 투구를 벗자 눈가리개가 다시 글래스로. 돌 뚜껑의 열쇠 구멍에서 빛이 새고, 구멍 모양 = 돔과 열두 점. 기록관의 고문서에 같은 문양과 꼬불꼬불한 선 — \"열쇠는 쇠가 아니라 말씀의 조각. 반은 여기, 반은 땅 위에.\" 아름 \"아빠 노트 1998년 페이지에 있어.\" 서울, 박사가 노트를 펴자 같은 선들(14화 비밀 열쇠 예고).",
     "scenes": 70,
