     "num": 15,
     "label": "15화",
     "title": "큰 용",
     "summary": "14화 다음 날 저녁. 미국·러시아·대한민국·유럽 우주 기지국이 동시에 **암흑물질**의 접근을 포착하고, 암흑물질이 각국 위성의 통신을 마비시켜 전 세계 미디어 송출이 막힌다(작가 확정 2026-10-17). 연구실 화면 속 암흑물질의 그림자는 퓨어랜드와 이어져 있다. 박사 \"큰 용이다.\" 아름의 등잔 열쇠가 다급하게 깜빡이고, 박사·하나·도윤은 연구실에서 기도하기로 한다. 골든 캐슬: 비룡 떼와 용장 셋(아포피스·낙심의 용장·뿔 꺾인 라합)이 성을 돌고, 서쪽 하늘이 갈라지며 **큰 용(옛 뱀)** — 깨진 거울 같은 비늘, 해를 가리는 날개 — 이 나타나 성 전체를 휘감는다. 큰 용의 잿빛 숨에 병사들은 비늘에 비친 자기 실패를 보고 무기를 떨군다. 천사장 미가엘이 막지만 천사 병사는 적다. 아름은 13화의 왕관 쓴 자기, 하임은 4화의 숨긴 영상을 비늘에서 보고 갑주가 흐려지지만, 은바와 서로의 손으로 돌아온다. 돔 한쪽이 크게 깨져 떨어진다(대균열). 남매가 숨은 방에서 둘이 말씀을 읽어도 빈 검 홈은 빛나지 않는다 — 부조는 **열두 사람이 함께 한 자루의 검을 드는** 모습. 기록관 \"꼭 이 성 안에 있어야 함께 읽는 것일까요?\" → 아름 \"…방송.\" 밤, 큰 용은 성을 감은 채 기다리고, 미가엘 \"새벽에 총공세가 온다.\" 1차 전쟁이 끝난 밤, 아름 \"위성이 막혔으면 기도로 보내요, 여기서.\" 남매·병사·천사·견습 창병이 큰 홀에서 함께 기도하고, 서울의 박사가 **글래스와 연결된 수신기**로 퓨어랜드에서 오는 기도를 받아 **에너지로 변환, 증폭기로 송출**한다(작가 확정 2026-10-17). 기도의 빛 한 줄기가 하늘로 오르고, 증폭기가 끝까지 차오르며 '퓨어랜드에서의 첫 방송'이 연결된다. 끝: 아름이 글래스 너머로 \"같이 읽어 주세요\" — 어두운 지구 곳곳에 작은 화면들이 켜진다(16화: 이 방송으로 암흑물질이 파괴되고 각국 미디어 센터가 돌아온다 + 함께 선포하는 말씀).",
