     "num": 16,
     "label": "16화",
     "title": "황금 성의 첫 방어전",
     "summary": "15화의 밤이 지나고 새벽. 큰 용이 골든 캐슬을 조여 오고, 남매·천사장 미가엘·천사 병사·기사·견습 창병이 성벽에서 버틴다. 서울에서는 박사가 증폭기 출력을 최대로 올리고, 퓨어랜드에서 시작된 아름의 방송이 위성 없이 서울·나이로비·도쿄·마드리드의 작은 화면들로 번진다. 방송을 따라 읽는 기도의 빛줄기가 궤도의 **암흑물질을 찢어** 위성 신호가 하나씩 돌아오고, 각국 미디어 센터가 다시 켜진다(작가 확정 2026-10-17). 방송을 따라 읽던 사람들 가운데 **열 명의 몸에서 빛이 일어나고**(미국·사우디·케냐·일본·스페인·이스라엘·독일·멕시코·가나·중국 — 얼굴은 가림), 큰 홀의 **열두 방패가 모두 켜진다**. 성벽과 전 세계가 함께 말씀을 선포하자 숨은 방의 빈 검 홈에서 **성령의 검**이 솟아 남매의 손에 들어오고, 둘이 함께 휘두른 빛이 큰 용의 거울 비늘을 부순다. 큰 용은 상처 입고 물러난다(죽지 않음). 이어 하늘이 열리며 **\"내 영을 만민에게 부어 주리니\"(요엘 2:28)** — 빛이 비처럼 퓨어랜드와 서울에 쏟아지고, 남매의 미완성 빛의 갑주가 거의 단단해진다(V4→V5 직전, 날개 없음 — 실체형과 날개는 2부). 돔 한 조각이 이어지고 해가 뜬다. 미가엘 \"열두 사람을 찾아라.\" 아름 \"만나러 가야겠다.\" — 1부 끝. 에필로그(시즌 2 새 그림체): 프랑스의 김미아 \"이 사람들, 만나야겠다\", 창유리의 사자 그림자(아리), 미국 봅슬레이 훈련장의 마이클 하트, 2030 사부아, 언덕 위 열두 실루엣 — 「열두 용사」.",
