     "num": 2,
     "label": "2화",
     "title": "라 플라뉴의 전복",
     "summary": "2030년 2월, 프랑스 사부아 라 플라뉴 동계올림픽. ESUV 시제품을 타고 도착한 박사·아름·밍토리에게 텍사스에서 온 대학원생 하임이 합류하고, 김미아가 일행을 맞는다. 안내를 맡은 통역 봉사자 **하루카**는 배운 적 없는 말도 \"들리면 안다\"(방언 통역의 은사). 밍토리는 루아가 14번 커브 위만 맴도는 것을 보고 불안해한다. 그날 새벽 선수촌 주방의 요리사이자 중국 지하교회 전도사 **리웨이**는 붉은 썰매가 뒤집히고 하얀 날개가 덮는 꿈을 꾸고, 경기장으로 달려와 하루카의 통역으로 경고한다. 결승, 미국 대표 **마이클 하트**의 썰매가 14번 커브에서 전복되고, 하임의 글래스에는 썰매를 덮는 하얀 날개가 보인다. 미국 팀 의료 봉사자 **캐털린**이 가장 먼저 달려가고, 구조대가 손쓰지 못하자 김미아가 박사를 데려오고, 미국 팀 주치의가 **AI 스캐너**를 대 보지만 약물 주입이 시작되지 않는다 — 그 순간 박사가 미리 말한 **영적 에너지 감지 장치**가 주치의 뒤에 서 있던 보조요원 **캐털린** 쪽으로 강하게 반응하고, 박사가 조심스럽게 건넨 스캐너가 그녀의 손에서 처음으로 켜져 나노 약물이 들어간다. 펜스 너머 일행의 기도가 빛의 실이 되어 날개로 모이고, 눈을 뜬 마이클은 아름에게 겹쳐 보이는 **빛의 갑주**를 본다(2부 첫 현실 가시화). 병실에서 갈비뼈 금 하나로 끝난 '기적'을 확인하고, 등잔 열쇠의 불꽃이 리웨이·하루카·캐털린을 가리킨다. **김미아는 \"필요한 건 제가 도울게요\"라며 조력자가 된다.** 퓨어랜드 큰 홀의 방패가 다섯으로 늘고, 미가엘은 \"얼음 위에서 내 손이 닿는 걸 느꼈다.\" 끝: 릴의 애니메이션 센터에서 이마리가 아름의 방송을 보며 \"…우리 아름이.\"",
