     "num": 5,
     "label": "5화",
     "title": "뉴욕 본사",
     "summary": "한 달 뒤 뉴욕. 김미아가 맨해튼 본사 꼭대기 층 전체를 **센터**로 내준다(\"마이클을 살려 주신 분들이에요\"). 지팡이를 짚고 걷는 **마이클**이 본사 대표 모델로 계약한다(김미아: \"선수는 다 나을 때까지 쉬는 거예요. 그게 계약 조건이에요\"). 박사의 오랜 동료 **로버트 J. 리 박사**(텍사스대 총장, ESUV 책임 연구원)가 ESUV 2호기의 슈퍼컴을 옮겨 와 기술 책임자로 합류하고, 그의 딸 **이미래**가 기록 담당으로 함께하며 하임과 반갑게 재회한다. **캐털린**은 손목 밴드와 짝을 이루는 스캐너 발전형을 익혀 마이클의 다리를 살핀다. 공정무역 직물 박람회에서 김미아 회사와 거래해 온 쿠스코의 직조공 **발렌티나 키스페**를 만나고, 그녀의 할머니 천에 열두 방패 무늬가 있다(\"등불을 든 아이가 오면 보여 줘라\"). 그날 밤 미래가 **아름의 딥페이크 영상**을 발견한다 — 퓨어데이는 연출이고 후원금은 김미아가 가져간다는 거짓. 스폰서가 빠지고, 영상 속 어둠에 큰 용의 붉은 눈이 스친다. 멕시코시티에서 첫 비행기로 온 인권 변호사 **디에고 라미레스**가 \"아름 씨는 '후원금'이라는 말을 한 번도 안 써요\"라며 거짓을 짚고, 아름의 기도에 **진리의 허리띠**가 빛난다(마이클·밍토리만 봄). 박사의 허리띠 모듈과 로버트의 서버가 조작된 프레임을 붉게 드러내고, 새벽 진실 방송과 디에고의 증언으로 흐름이 바뀐다(요 8:32). 디에고의 손에 빛이 맺히며 **열 번째 방패**(지혜의 말씀). 갈렙: \"방패 밖에서 천을 지켜 온 손이 하나 더 왔구나.\" 끝: 발렌티나가 천의 반쪽과 안데스 방패 조각이 쿠스코에 있다고 말한다 → 6화 「안데스의 방패」.",
