     "num": 8,
     "label": "8화",
     "title": "예루살렘의 화해",
     "summary": "2030년 4월 예루살렘(작품 속 미래 설정). 아름의 고교 친구 **올렛**이 도착한다(\"아름이 방송에 몰래 댓글 단 사람이 저예요\"). 성벽 밖 공동 발굴 현장에서 **라일라**와 이스라엘의 고고학도 **노아 벤아미**가 같은 구역을 맡지만, 작업대는 둘로 나뉘어 있다. 두 팀 사이에서 열두 방패가 새겨진 돌이 나오자 노아는 \"이스라엘 역사로\", 라일라는 \"이스라엘만의 이야기가 아니\"라고 정중하지만 단호하게 맞선다. 아름과 올렛이 \"말이 아니라 평안을 들고\" 빵과 물을 들고 두 테이블 사이로 걸어 들어가고, 발걸음마다 빛이 남는다 — **평안의 복음의 신**(엡 6:15). 밍토리는 흰 비둘기와 회색 비둘기가 돌 위에 나란히 앉는 것을 본다. 노아가 하늘을 보다 **경보의 환상**(\"아래쪽 수로, 물이 들어와요\")을 받고, 수로 측량 중 돌무더기에 발이 낀 라일라를 맨손으로 구해 낸다(\"같은 역사를 보고 있는 사람이잖아요\"). **올렛이 기도**하자 라일라는 빛 속에서 못 자국 난 손의 **예수님**을 만나고(\"딸아, 평안히 가라\" 눅 8:48), \"이분이 예수님이에요?\" — \"라일라 씨를 아주 오래 기다리셨대요.\" 라일라의 발목과 노아의 상처 난 손이 함께 낫는다. 두 사람은 서로 사과하고 끌어안으며, 빛의 발자국이 두 사람 발밑까지 이어진다. 돌을 함께 읽는다(\"하나님께서 여러 역사에 같은 약속을 새기신 거네요\"). 퓨어랜드에서 마지막 두 방패가 켜지고 **열두 방패가 모두 깨어난다**(갈렙: \"가르치는 자, 그리고 깨어 경고하는 자. 열둘이 모두 깨어났다\"). 노을 진 옥상, 열두 명이 다 모였다는 박사, 아름과 올렛, 흩어진 동료들의 메시지 — \"모두 골든 캐슬에서 만나요.\" → 9화 「열두 용사」.",
